<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../api/client'
import { money, labels } from '../utils/format'
import AgentTeamReport from '../components/AgentTeamReport.vue'
import RecordTable from '../components/RecordTable.vue'
const media=window.matchMedia('(min-width: 761px)'),wide=ref(media.matches)
const updateWidth=()=>{wide.value=media.matches}
onMounted(()=>media.addEventListener('change',updateWidth))
onUnmounted(()=>media.removeEventListener('change',updateWidth))
interface Level { id:number;name:string;active:boolean;sort:number }
const tab=ref('agents'),loading=ref(false),busy=ref(false),rows=ref<any[]>([]),levels=ref<Level[]>([]),q=ref(''),page=ref(1),total=ref(0),filterLevel=ref<number>()
const parentId=ref<number>()
const dialog=ref(''),selected=ref<any>(null),assignment=ref<number>(),levelForm=reactive({name:'',active:true,sort:0})
const pricing=reactive({kind:'agent',id:0,title:''}),priceRows=ref<any[]>([]),pricePage=ref(1),priceTotal=ref(0),priceQ=ref(''),priceLoading=ref(false),saving=ref<number>()
const agentColumns=[{key:'id',label:'用户ID',width:75},{key:'email',label:'代理邮箱',width:220},{key:'name',label:'昵称'},{key:'level_name',label:'代理等级'},{key:'level_active',label:'等级状态',type:'boolean'},{key:'active',label:'账号状态',type:'boolean'},{key:'parent_id',label:'上级代理ID',width:110}]
async function load(){loading.value=true;try{levels.value=(await api.get('/admin/agent-levels')).data;const{data}=await api.get('/admin/agents',{params:{q:q.value,page:page.value,level_id:filterLevel.value}});rows.value=data.items;total.value=data.total}finally{loading.value=false}}
function openLevel(value?:Level){selected.value=value||null;Object.assign(levelForm,value?{name:value.name,active:value.active,sort:value.sort}:{name:'',active:true,sort:0});dialog.value='level'}
async function saveLevel(){busy.value=true;try{await(selected.value?api.put(`/admin/agent-levels/${selected.value.id}`,levelForm):api.post('/admin/agent-levels',levelForm));dialog.value='';ElMessage.success('代理等级已保存');await load()}finally{busy.value=false}}
function openAssignment(value:any){selected.value=value;assignment.value=value.level_id;dialog.value='assignment'}
async function saveAssignment(){busy.value=true;try{await api.put(`/admin/agents/${selected.value.id}/level`,{level_id:assignment.value});dialog.value='';ElMessage.success('代理等级已更新');await load()}finally{busy.value=false}}
async function openPricing(kind:'agent'|'level',value:any){Object.assign(pricing,{kind,id:value.id,title:kind==='agent'?value.email:value.name});pricePage.value=1;priceQ.value='';priceRows.value=[];dialog.value='pricing';await loadPrices()}
async function loadPrices(){priceLoading.value=true;try{const base=pricing.kind==='agent'?`/admin/agents/${pricing.id}/products`:`/admin/agent-levels/${pricing.id}/prices`;const{data}=await api.get(base,{params:{page:pricePage.value,q:priceQ.value}});priceRows.value=data.items.map((row:any)=>({...row,draft_price:pricing.kind==='agent'?row.override_price:row.level_price,draft_allowed:row.allowed??true}));priceTotal.value=data.total}finally{priceLoading.value=false}}
async function savePrice(row:any){
 if(pricing.kind==='level' && row.draft_price==null){ElMessage.warning('请输入等级价，或使用「恢复继承」');return}
 saving.value=row.id
 try{const url=pricing.kind==='agent'?`/admin/agents/${pricing.id}/products/${row.id}`:`/admin/agent-levels/${pricing.id}/prices/${row.id}`;await api.put(url,pricing.kind==='agent'?{price:row.draft_price??null,allowed:row.draft_allowed}:{price:row.draft_price});ElMessage.success('定价与权限已保存');await loadPrices()}finally{saving.value=undefined}
}
async function resetPrice(row:any){try{await ElMessageBox.confirm('确认清除这项自定义配置，恢复继承价格和默认采购权限？','恢复继承',{type:'warning'})}catch{return}saving.value=row.id;try{await api.delete(pricing.kind==='agent'?`/admin/agents/${pricing.id}/products/${row.id}`:`/admin/agent-levels/${pricing.id}/prices/${row.id}`);ElMessage.success('已恢复继承');await loadPrices()}finally{saving.value=undefined}}
async function saveParent(){busy.value=true;try{await api.put(`/admin/agents/${selected.value.id}/parent`,{parent_id:parentId.value??null,expected_parent_id:selected.value.parent_id??null});dialog.value='';ElMessage.success('代理归属已保存');await load()}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="section-heading"><div><p class="eyebrow">PARTNER CONFIGURATION</p><h1>代理管理</h1><p class="muted">统一配置代理等级、专属采购价和商品权限，所有变更记录审计。</p></div><el-button @click="load" :loading="loading">刷新数据</el-button></div><el-alert title="价格优先级：指定代理专属价 → 等级价 → 默认代理价 → 零售价。停用等级或禁止商品采购会阻止新的钱包购买，已有订单与卡密不受影响。" type="info" :closable="false" class="spaced"/>
<section class="panel table-panel"><el-tabs v-model="tab"><el-tab-pane label="代理列表" name="agents"><div class="toolbar spaced"><el-input v-model="q" placeholder="搜索代理邮箱" aria-label="搜索代理邮箱" clearable style="width:240px" @keyup.enter="page=1;load()"/><el-select v-model="filterLevel" placeholder="全部等级" aria-label="筛选代理等级" clearable style="width:180px" @change="page=1;load()"><el-option v-for="level in levels" :key="level.id" :value="level.id" :label="level.name"/></el-select><el-button @click="page=1;load()">查询</el-button><router-link to="/admin/users">在用户管理中授予代理角色 →</router-link></div><RecordTable :rows="rows" :columns="agentColumns" :loading="loading"><el-table-column label="配置" min-width="320" :fixed="wide ? 'right' : false"><template #default="{row}"><el-button link type="primary" @click="selected=row;parentId=row.parent_id??undefined;dialog='parent'">设置上级</el-button><el-button link type="primary" @click="selected=row;dialog='team'">名下业绩</el-button><el-button link type="primary" @click="openAssignment(row)">设置等级</el-button><el-button link type="primary" @click="openPricing('agent',row)">商品权限与价格</el-button></template></el-table-column></RecordTable><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load"/></el-tab-pane>
<el-tab-pane label="等级与定价" name="levels"><div class="toolbar spaced"><el-button type="primary" @click="openLevel()">＋ 新建等级</el-button></div><el-table :data="levels" empty-text="暂无代理等级"><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="name" label="等级名称" min-width="160"/><el-table-column prop="sort" label="排序" width="100"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{row.active?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="配置" min-width="170"><template #default="{row}"><el-button link type="primary" @click="openLevel(row)">编辑等级</el-button><el-button link type="primary" @click="openPricing('level',row)">配置等级价</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></section>
<el-dialog :model-value="dialog==='parent'" @close="dialog=''" title="设置上级代理" width="min(94vw,480px)"><p>{{selected?.email}}</p><el-alert title="仅支持直属一级关系。清空ID解除归属；不会转移钱包、订单、卡密或自动结算佣金。" :closable="false" class="spaced"/><form @submit.prevent="saveParent"><label>上级代理ID<el-input-number v-model="parentId" :min="1" :max="2147483647" :precision="0" /></label><el-button type="primary" native-type="submit" :loading="busy">保存代理归属</el-button></form></el-dialog>
<el-dialog :model-value="dialog==='team'" @close="dialog=''" :title="`名下业绩 · ${selected?.email||''}`" width="min(96vw,1100px)"><AgentTeamReport v-if="dialog==='team'" :key="selected.id" :parent-id="selected.id" /></el-dialog>
<el-dialog :model-value="dialog==='level'" @close="dialog=''" :title="selected?'编辑代理等级':'新建代理等级'" width="min(94vw,480px)"><form @submit.prevent="saveLevel"><label>等级名称<input v-model.trim="levelForm.name" maxlength="40" required/></label><label>显示排序<el-input-number v-model="levelForm.sort" :min="-1000000" :max="1000000" :precision="0"/></label><label class="switch-label">启用等级<el-switch v-model="levelForm.active"/></label><el-alert v-if="!levelForm.active" title="停用后，该等级的所有代理将暂停新采购。已有订单和卡密继续保留。" type="warning" :closable="false" class="spaced"/><el-button type="primary" native-type="submit" :loading="busy">保存等级</el-button></form></el-dialog>
<el-dialog :model-value="dialog==='assignment'" @close="dialog=''" title="设置代理等级" width="min(94vw,480px)"><p class="muted">{{selected?.email}}</p><form @submit.prevent="saveAssignment"><label>代理等级<el-select v-model="assignment" aria-label="代理等级"><el-option v-for="level in levels.filter(l=>l.active)" :key="level.id" :value="level.id" :label="level.name"/></el-select></label><el-button type="primary" native-type="submit" :loading="busy" :disabled="!assignment">确认设置等级</el-button></form></el-dialog>
<el-dialog :model-value="dialog==='pricing'" @close="dialog=''" :title="`${pricing.kind==='agent'?'商品权限与价格':'配置等级价'} · ${pricing.title}`" width="min(96vw,1100px)" :close-on-click-modal="false"><p class="muted">{{pricing.kind==='agent'?'清空专属价并保存可继承等级价；禁止采购会由服务端直接拒绝。':'为每个商品设置该等级的采购价；未设置时继承默认代理价。'}} 金额单位为分。</p><form class="toolbar spaced" @submit.prevent="pricePage=1;loadPrices()"><el-input v-model="priceQ" placeholder="搜索商品名称" aria-label="搜索商品名称" style="width:220px" clearable/><el-button native-type="submit">搜索商品</el-button></form><el-table :data="priceRows" v-loading="priceLoading" empty-text="暂无商品" class="pricing-table"><el-table-column prop="name" label="商品" min-width="180"/><el-table-column label="零售价" width="110"><template #default="{row}">{{money(row.price)}}</template></el-table-column><el-table-column v-if="pricing.kind==='agent'" label="当前生效价格" min-width="140"><template #default="{row}">{{money(row.effective_price)}}<small class="muted"> / {{labels[row.price_source]}}</small><p v-if="row.restriction" class="form-error">{{row.restriction}}</p></template></el-table-column><el-table-column :label="pricing.kind==='agent'?'专属价（分）':'等级价（分）'" min-width="180"><template #default="{row}"><el-input-number v-model="row.draft_price" :aria-label="`${row.name}${pricing.kind==='agent'?'专属价':'等级价'}（分）`" :min="0" :max="100000000" :precision="0" placeholder="继承" style="width:150px"/></template></el-table-column><el-table-column v-if="pricing.kind==='agent'" label="允许采购" width="100"><template #default="{row}"><el-switch v-model="row.draft_allowed" :aria-label="`${row.name}允许采购`"/></template></el-table-column><el-table-column label="操作" width="180" :fixed="wide ? 'right' : false"><template #default="{row}"><el-button link type="primary" :loading="saving===row.id" @click="savePrice(row)">保存配置</el-button><el-button link :disabled="saving===row.id" @click="resetPrice(row)">恢复继承</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="pricePage" :total="priceTotal" :page-size="20" layout="total,prev,pager,next" @current-change="loadPrices"/></el-dialog></template>
